    bool hit    = hit_fault(total0, fault_alloc_total(), fault_at);

    if (rc == 0) {
        SWEEP_CHECK(!hit, "insert %s hit the injected fault but returned 0", keys[i]);
        m->present[i] = true;
        m->value[i]   = v;
        m->count++;
        (*accepted)++;
        return;
