void pool_stats(const rb_pool_t *p,
                size_t *slabs, size_t *live, size_t *free_objs)
{
    if (slabs != NULL) {
        *slabs = p->nslabs;
    }
    if (live != NULL) {
        *live = p->live;
    }
    if (free_objs != NULL) {
        *free_objs = p->nfree + p->uncarved;
    }
