    for (const struct slab *s = p->slabs; s != NULL; s = s->next) {
        uintptr_t first = (uintptr_t)s + p->g.header;
        uintptr_t end   = first + p->g.objs_per_slab * p->g.stride;
        if (a >= first && a < end) {
