{
    pool_failures = 0;
    test_geometry();
    test_alloc_free_stress();
    test_lifo_reuse_and_nulls();
    test_poison();
    test_fault_paths();
    if (pool_failures == 0) {
        printf("pool unit tests: ok\n");
    }
    return pool_failures;
}

