1	#include "rbtree.h"
2	#include "fault_alloc.h"   /* rb_malloc / rb_free: the allocation seam */
3	#include "pool.h"          /* node storage for pooled trees (M2) */
4	
5	#include <string.h>
6	
7	/* Every allocation in this file goes through rb_malloc/rb_free, never
8	 * malloc/free directly. They live in tests/fault_alloc.c now, so the fault
9	 * injector can sit underneath the tree without the tree code changing.
10	 * <stdlib.h> is deliberately not included: a direct malloc/free here would
11	 * fail to compile. */
12	
13	/* A node is red or black. There is no third color -- deletion's "doubly
14	 * black" is a way of counting, never a value stored in a node. */
15	typedef enum { RB_RED, RB_BLACK } rb_color;
16	
17	struct rbnode {
18	    char          *key;      /* our own copy of the caller's string; we free it */
19	    void          *value;    /* the caller's pointer, stored as-is (not copied) */
20	    rb_color       color;
21	    struct rbnode *left;     /* NULL when there is no child */
22	    struct rbnode *right;
23	    struct rbnode *parent;   /* NULL only for the root */
24	};
25	
26	struct rbtree {
27	    struct rbnode   *root;       /* NULL when the tree is empty */
28	    rb_value_free_fn value_free; /* NULL means the values are not ours to free */
29	    size_t           count;      /* keys held, so rb_size answers instantly */
30	    rb_pool_t       *pool;       /* where nodes live; NULL = one rb_malloc per node */
31	};
32	
33	/* ------------------------------------------------------------------------
34	 * Node lifetime. One node is TWO allocations: the struct, and a private copy
35	 * of the key. Both are made here and both are freed in node_release, so the
36	 * ownership rules live in exactly one place. In a pooled tree the struct
37	 * comes from t->pool instead of rb_malloc; the key copy is variable-length,
38	 * so it always comes from rb_malloc.
39	 * --------------------------------------------------------------------- */
40	
41	/* Give a node's struct back to wherever it came from. */
42	static void node_storage_free(const rbtree_t *t, struct rbnode *n)
43	{
44	    if (t->pool != NULL) {
45	        pool_free(t->pool, n);
46	    } else {
47	        rb_free(n);
48	    }
49	}
50	
51	/* Returns NULL if either allocation fails. On failure nothing is left
52	 * allocated -- the caller never sees a half-built node. */
53	static struct rbnode *node_alloc(const rbtree_t *t, const char *key, void *value)
54	{
55	    struct rbnode *n = (t->pool != NULL) ? pool_alloc(t->pool) : rb_malloc(sizeof *n);
56	    if (n == NULL) {
57	        return NULL;
58	    }
59	
60	    size_t len = strlen(key) + 1;           /* +1 for the '\0' terminator */
61	    n->key = rb_malloc(len);
62	    if (n->key == NULL) {
63	        goto fail;                          /* unwind the first allocation */
64	    }
65	    memcpy(n->key, key, len);
66	
67	    n->value  = value;
68	    n->color  = RB_RED;                     /* a new node is always red */
69	    n->left   = NULL;
70	    n->right  = NULL;
71	    n->parent = NULL;
72	    return n;
73	
74	fail:
75	    node_storage_free(t, n);
76	    return NULL;
77	}
78	
79	/* Free one node: the value (only if the tree owns values), the key copy, and
80	 * the struct. Does not touch left/right/parent -- unlinking is the caller's
81	 * job, and this must never be called on a node still reachable from the tree. */
82	static void node_release(const rbtree_t *t, struct rbnode *n)
83	{
84	    if (t->value_free != NULL) {
85	        t->value_free(n->value);
86	    }
87	    rb_free(n->key);
88	    node_storage_free(t, n);
89	}
90	
91	/* rb_validate failure codes. 0 means every rule holds. Nonzero names the rule
92	 * that broke, which is far more useful in a failing test than a bare 1. */
93	enum {
94	    RB_OK              = 0,
95	    RB_BAD_ORDER       = 1,     /* in-order keys are not strictly increasing */
96	    RB_BAD_PARENT      = 2,     /* a child's parent pointer does not point back */
97	    RB_BAD_COUNT       = 3,     /* t->count disagrees with the real node count */
98	    RB_BAD_ROOT_PARENT = 4,     /* the root has a non-NULL parent */
99	    RB_BAD_ROOT_COLOR  = 5,     /* rule 2: the root is not black */
100	    RB_BAD_RED_RED     = 6,     /* rule 4: a red node has a red child */
101	    RB_BAD_BLACK_HEIGHT= 7,     /* rule 5: left and right black-heights differ */
102	};
103	
104	/* ------------------------------------------------------------------------
105	 * Balancing: rotations and the insert fixup.
106	 * --------------------------------------------------------------------- */
107	
108	/* A missing child counts as black (rule 3), so NULL is never red. Every
109	 * color test below goes through here so that rule lives in exactly one place. */
110	static bool is_red(const struct rbnode *n)
111	{
112	    return n != NULL && n->color == RB_RED;
113	}
114	
115	/* Left rotation at x. Precondition: x->right is a real node, never NULL.
116	 *
117	 *        x                  y
118	 *       / \                / \
119	 *      a   y      ==>      x   c
120	 *         / \            / \
121	 *        b   c          a   b
122	 *
123	 * Shape only: no key, value, or color changes, and nothing is allocated or
124	 * freed. The three-way reattach in the middle is what keeps t->root correct
125	 * when x was the root -- the caller never has to think about it. */
126	static void rotate_left(rbtree_t *t, struct rbnode *x)
127	{
128	    struct rbnode *y = x->right;
129	
130	    x->right = y->left;                     /* b moves across to x */
131	    if (y->left != NULL) {
132	        y->left->parent = x;
133	    }
134	
135	    y->parent = x->parent;                  /* y takes x's old place... */
136	    if (x->parent == NULL) {
137	        t->root = y;                        /* ...which was the root */
138	    } else if (x == x->parent->left) {
139	        x->parent->left = y;
140	    } else {
141	        x->parent->right = y;
142	    }
143	
144	    y->left = x;                            /* x tucks under y */
145	    x->parent = y;
146	}
147	
148	/* Right rotation at x: the mirror image. Precondition: x->left is not NULL. */
149	static void rotate_right(rbtree_t *t, struct rbnode *x)
150	{
151	    struct rbnode *y = x->left;
152	
153	    x->left = y->right;
154	    if (y->right != NULL) {
155	        y->right->parent = x;
156	    }
157	
158	    y->parent = x->parent;
159	    if (x->parent == NULL) {
160	        t->root = y;
161	    } else if (x == x->parent->right) {
162	        x->parent->right = y;
163	    } else {
164	        x->parent->left = y;
165	    }
166	
167	    y->right = x;
168	    x->parent = y;
169	}
170	
171	/* Restore the red-black rules after inserting z, which is red.
172	 *
173	 * Loop invariant: z is red; the root is black unless z is the root; and the
174	 * only rule that can be broken is rule 4 at exactly one spot -- z and its
175	 * parent both red. Rule 5 (equal black-heights on every path) holds the
176	 * whole time, because a red node adds nothing to any path's black count.
177	 *
178	 * Termination: the red-uncle case moves z up two levels without rotating, so
179	 * it can repeat at most height/2 times. The black-uncle cases rotate and
180	 * leave z's parent black, so the loop exits on the very next check. At most
181	 * two rotations in total. */
182	static void insert_fixup(rbtree_t *t, struct rbnode *z)
183	{
184	    while (is_red(z->parent)) {
185	        struct rbnode *p = z->parent;
186	        struct rbnode *g = p->parent;       /* p is red, so p is not the root */
187	
188	        if (p == g->left) {
189	            struct rbnode *u = g->right;    /* uncle; NULL counts as black */
190	
191	            if (is_red(u)) {
192	                /* Case 1: red uncle. Recolor and climb. No pointers move. */
193	                p->color = RB_BLACK;
194	                u->color = RB_BLACK;
195	                g->color = RB_RED;
196	                z = g;
197	            } else {
198	                if (z == p->right) {
199	                    /* Case 2: zig-zag. Straighten it, then fall into case 3.
200	                     * The rotation changes who is above whom, so re-read
201	                     * p and g afterward -- the old ones are stale. */
202	                    z = p;
203	                    rotate_left(t, z);
204	                    p = z->parent;
205	                    g = p->parent;
206	                }
207	                /* Case 3: straight line. One rotation at g fixes it, and
208	                 * p is now black, so the loop ends. */
209	                p->color = RB_BLACK;
210	                g->color = RB_RED;
211	                rotate_right(t, g);
212	            }
213	        } else {
214	            /* Mirror of the block above: every left and right swapped. */
215	            struct rbnode *u = g->left;
216	
217	            if (is_red(u)) {
218	                p->color = RB_BLACK;
219	                u->color = RB_BLACK;
220	                g->color = RB_RED;
221	                z = g;
222	            } else {
223	                if (z == p->left) {
224	                    z = p;
225	                    rotate_right(t, z);
226	                    p = z->parent;
227	                    g = p->parent;
228	                }
229	                p->color = RB_BLACK;
230	                g->color = RB_RED;
231	                rotate_left(t, g);
232	            }
233	        }
234	    }
235	
236	    t->root->color = RB_BLACK;              /* rule 2, unconditionally */
237	}
238	
239	rbtree_t *rb_create(rb_value_free_fn value_free)
240	{
241	    rbtree_t *t = rb_malloc(sizeof *t);
242	    if (t == NULL) {
243	        return NULL;
244	    }
245	    t->root = NULL;
246	    t->value_free = value_free;
247	    t->count = 0;
248	    t->pool = NULL;
249	    return t;
250	}
251	
252	/* Two allocations: the tree struct, then the pool (which takes no slab until
253	 * the first node is inserted). If the pool fails, give the struct back. */
254	rbtree_t *rb_create_pooled(rb_value_free_fn value_free)
255	{
256	    rbtree_t *t = rb_create(value_free);
257	    if (t == NULL) {
258	        return NULL;
259	    }
260	    t->pool = pool_create(sizeof(struct rbnode));
261	    if (t->pool == NULL) {
262	        rb_free(t);                         /* unwind the first allocation */
263	        return NULL;
264	    }
265	    return t;
266	}
267	
268	int rb_insert(rbtree_t *t, const char *key, void *value)
269	{
270	    struct rbnode *parent = NULL;
271	    struct rbnode *cur = t->root;
272	    int cmp = 0;
273	
274	    /* Invariant: key is not in any node above cur, and if it is in the tree
275	     * at all it is somewhere in the subtree rooted at cur. */
276	    while (cur != NULL) {
277	        cmp = strcmp(key, cur->key);
278	        if (cmp == 0) {
279	            /* Key already present: replace the value. Store the new pointer
280	             * FIRST, then free the old one: value_free is caller code, and
281	             * while it runs the node must not point at memory being freed
282	             * (a callback that called rb_find would get a dangling pointer).
283	             * The tree is the old value's only owner, so freeing it is right
284	             * (if we own values) -- unless the caller handed back the very
285	             * pointer we already hold; then there is nothing old to free,
286	             * and freeing it would leave cur->value dangling for rb_destroy
287	             * to free again. */
288	            void *old = cur->value;
289	            cur->value = value;
290	            if (t->value_free != NULL && old != value) {
291	                t->value_free(old);
292	            }
293	            return 0;                       /* count unchanged */
294	        }
295	        parent = cur;
296	        cur = (cmp < 0) ? cur->left : cur->right;
297	    }
298	
299	    /* Fell off the tree: cur is NULL and parent is the node to hang from.
300	     * cmp still holds the comparison against parent, so it tells us which side. */
301	    struct rbnode *n = node_alloc(t, key, value);
302	    if (n == NULL) {
303	        return -1;                          /* tree unchanged; caller keeps value */
304	    }
305	    n->parent = parent;
306	
307	    if (parent == NULL) {
308	        t->root = n;                        /* first node in an empty tree */
309	    } else if (cmp < 0) {
310	        parent->left = n;
311	    } else {
312	        parent->right = n;
313	    }
314	    t->count++;
315	
316	    insert_fixup(t, n);
317	    return 0;
318	}
319	
320	void *rb_find(const rbtree_t *t, const char *key)
321	{
322	    const struct rbnode *cur = t->root;
323	
324	    /* Invariant: if key is in the tree, it is in the subtree rooted at cur. */
325	    while (cur != NULL) {
326	        int cmp = strcmp(key, cur->key);
327	        if (cmp == 0) {
328	            return cur->value;
329	        }
330	        cur = (cmp < 0) ? cur->left : cur->right;
331	    }
332	    return NULL;
333	}
334	
335	/* ------------------------------------------------------------------------
336	 * Deletion. Kept apart from the insert machinery so a failing delete test
337	 * points at exactly these functions. Nothing here allocates: the header
338	 * gives rb_delete no way to report an allocation failure, so it must never
339	 * need one. No recursion either: delete and its fixup are loops.
340	 * --------------------------------------------------------------------- */
341	
342	/* Leftmost node under n: the smallest key in that subtree. Precondition: n
343	 * is not NULL. Used to find the in-order successor of a node with two
344	 * children (the minimum of its right subtree). */
345	static struct rbnode *tree_minimum(struct rbnode *n)
346	{
347	    /* Invariant: the smallest key of the original subtree is at or below n. */
348	    while (n->left != NULL) {
349	        n = n->left;
350	    }
351	    return n;
352	}
353	
354	/* Make u's parent point at v instead of u. v may be NULL. Updates t->root
355	 * when u was the root. Does not touch u's own pointers, and cannot set
356	 * v->parent when v is NULL -- which is why delete_fixup is handed the
357	 * parent separately. */
358	static void transplant(rbtree_t *t, struct rbnode *u, struct rbnode *v)
359	{
360	    if (u->parent == NULL) {
361	        t->root = v;
362	    } else if (u == u->parent->left) {
363	        u->parent->left = v;
364	    } else {
365	        u->parent->right = v;
366	    }
367	    if (v != NULL) {
368	        v->parent = u->parent;
369	    }
370	}
371	
372	/* Pay off the "doubly black" debt left behind by unlinking a black node.
373	 *
374	 * x is whatever took the unlinked node's place -- possibly NULL, since a
375	 * missing child counts as black -- and x_parent is its parent. Every path
376	 * through x is now one black short of every other path. The loop climbs
377	 * toward the root until the debt is paid, in one of three ways: a red node
378	 * absorbs it by turning black, a rotation drags a red node across from the
379	 * sibling's side, or the debt reaches the root and simply dissolves (every
380	 * path lost the same one black, so they are all still equal).
381	 *
382	 * Loop invariant: x is doubly black; every other rule holds. The sibling w
383	 * is never NULL: before the delete both of x_parent's sides had the same
384	 * black-height, and a black node came off x's side, so the sibling's side
385	 * still has black-height >= 2 -- which takes at least one real node. That
386	 * is also why, when x is NULL, "x == x_parent->left" still picks the right
387	 * side: only the emptied side can be NULL.
388	 *
389	 * Termination: case 2 climbs one level per pass, so at most height passes.
390	 * Case 1 always drops into 2, 3 or 4 with a black sibling; if it is 2, the
391	 * new x is the parent we just painted red, so the next test exits. Cases
392	 * 3->4 and 4 end the loop directly. At most three rotations in total. */
393	static void delete_fixup(rbtree_t *t, struct rbnode *x, struct rbnode *x_parent)
394	{
395	    while (x != t->root && !is_red(x)) {
396	        if (x == x_parent->left) {
397	            struct rbnode *w = x_parent->right;     /* sibling; never NULL */
398	
399	            if (is_red(w)) {
400	                /* Case 1: red sibling. Not a shape we can fix directly, so
401	                 * rotate to give x a black sibling, then fall through. */
402	                w->color = RB_BLACK;
403	                x_parent->color = RB_RED;
404	                rotate_left(t, x_parent);
405	                w = x_parent->right;                /* new sibling, black */
406	            }
407	
408	            if (!is_red(w->left) && !is_red(w->right)) {
409	                /* Case 2: black sibling, no red child. Take one black off
410	                 * the sibling's side as well (paint w red): now both sides
411	                 * are short by one, so the debt moves up to the parent. */
412	                w->color = RB_RED;
413	                x = x_parent;
414	                x_parent = x->parent;
415	            } else {
416	                if (!is_red(w->right)) {
417	                    /* Case 3: the red child is on the near side. Rotate at
418	                     * w to move it to the far side, then fall into case 4. */
419	                    w->left->color = RB_BLACK;
420	                    w->color = RB_RED;
421	                    rotate_right(t, w);
422	                    w = x_parent->right;
423	                }
424	                /* Case 4: red child on the far side. Rotate at the parent
425	                 * so w moves up and the red child comes across to x's side;
426	                 * the recoloring restores every path's black count. Paid. */
427	                w->color = x_parent->color;
428	                x_parent->color = RB_BLACK;
429	                w->right->color = RB_BLACK;
430	                rotate_left(t, x_parent);
431	                x = t->root;                        /* done: ends the loop */
432	                x_parent = NULL;
433	            }
434	        } else {
435	            /* Mirror of the block above: every left and right swapped. */
436	            struct rbnode *w = x_parent->left;
437	
438	            if (is_red(w)) {
439	                w->color = RB_BLACK;
440	                x_parent->color = RB_RED;
441	                rotate_right(t, x_parent);
442	                w = x_parent->left;
443	            }
444	
445	            if (!is_red(w->right) && !is_red(w->left)) {
446	                w->color = RB_RED;
447	                x = x_parent;
448	                x_parent = x->parent;
449	            } else {
450	                if (!is_red(w->left)) {
451	                    w->right->color = RB_BLACK;
452	                    w->color = RB_RED;
453	                    rotate_left(t, w);
454	                    w = x_parent->left;
455	                }
456	                w->color = x_parent->color;
457	                x_parent->color = RB_BLACK;
458	                w->left->color = RB_BLACK;
459	                rotate_right(t, x_parent);
460	                x = t->root;
461	                x_parent = NULL;
462	            }
463	        }
464	    }
465	
466	    if (x != NULL) {
467	        x->color = RB_BLACK;    /* a red x absorbs the debt; the root stays black */
468	    }
469	}
470	
471	int rb_delete(rbtree_t *t, const char *key)
472	{
473	    struct rbnode *z = t->root;
474	
475	    /* Invariant: if key is in the tree, it is in the subtree rooted at z. */
476	    while (z != NULL) {
477	        int cmp = strcmp(key, z->key);
478	        if (cmp == 0) {
479	            break;
480	        }
481	        z = (cmp < 0) ? z->left : z->right;
482	    }
483	    if (z == NULL) {
484	        return -1;                          /* absent: nothing touched */
485	    }
486	
487	    if (z->left != NULL && z->right != NULL) {
488	        /* Two children: hoist. The in-order successor y is the smallest key
489	         * to z's right, so it has no left child. Swap the payloads: z's slot
490	         * now holds y's key/value (still in order), and y's node holds the
491	         * doomed key/value. Then delete y's node instead. Colors stay put --
492	         * the tree's shape and coloring are untouched, only the payload
493	         * moved -- and each key and value still has exactly one owner. */
494	        struct rbnode *y = tree_minimum(z->right);
495	        char *k = z->key;
496	        void *v = z->value;
497	        z->key = y->key;
498	        z->value = y->value;
499	        y->key = k;
500	        y->value = v;
501	        z = y;
502	    }
503	
504	    /* z has at most one child. Splice z out: x takes its place. */
505	    struct rbnode *x = (z->left != NULL) ? z->left : z->right;  /* may be NULL */
506	    struct rbnode *x_parent = z->parent;
507	
508	    transplant(t, z, x);                    /* unlinked: nothing points at z now */
509	    t->count--;
510	
511	    if (z->color == RB_BLACK) {
512	        /* Unlinking a black node left every path through x one black short.
513	         * Unlinking a red one cost nothing. z is unlinked but not yet freed,
514	         * and x and x_parent are never z, so the fixup never sees it. */
515	        delete_fixup(t, x, x_parent);
516	    }
517	
518	    /* Free z LAST. node_release runs value_free, which is caller code: if it
519	     * looks at the tree (rb_size, rb_find, rb_validate), it must see a
520	     * finished delete -- count right, every rule holding -- not one caught
521	     * halfway. Nothing above reads z after this line. */
522	    node_release(t, z);
523	    return 0;
524	}
525	
526	size_t rb_size(const rbtree_t *t)
527	{
528	    return (t == NULL) ? 0 : t->count;
529	}
530	
531	/* In-order walk of one subtree: everything smaller, then this node, then
532	 * everything larger. Recursion is allowed here for this assignment (HW2
533	 * takes it away). The callback must not insert into or delete from the
534	 * tree it is walking -- the walk holds pointers into it. */
535	/* The node right after n in key order, or NULL if n is the last one.
536	 * If n has a right subtree, the next key is that subtree's smallest.
537	 * Otherwise climb: while we come up from a RIGHT child, that parent was
538	 * already visited (it is smaller than n). The first parent we reach from a
539	 * LEFT child is the next one. Climbing off the root means n was the last. */
540	static const struct rbnode *successor(const struct rbnode *n)
541	{
542	    if (n->right != NULL) {
543	        return tree_minimum(n->right);
544	    }
545	    const struct rbnode *p = n->parent;
546	    while (p != NULL && n == p->right) {
547	        n = p;
548	        p = p->parent;
549	    }
550	    return p;
551	}
552	
553	/* In-order walk with no recursion: the only state is one node pointer, and
554	 * the way back up lives in the nodes' own parent pointers. The tree is never
555	 * modified, so the const on t is honest.
556	 *
557	 * Callback contract: fn may READ the tree (rb_find, rb_size, rb_validate,
558	 * even another rb_foreach). It must not insert or delete: the next node is
559	 * worked out after fn returns, from the node fn was just given, so removing
560	 * nodes under the walk is undefined. A callback that never returns: don't. */
561	void rb_foreach(const rbtree_t *t,
562	                void (*fn)(const char *key, void *value, void *ctx),
563	                void *ctx)
564	{
565	    if (t->root == NULL) {
566	        return;
567	    }
568	    /* Invariant: every key smaller than n's has been handed to fn exactly
569	     * once, and n's and the larger ones not yet. */
570	    for (const struct rbnode *n = tree_minimum(t->root); n != NULL; n = successor(n)) {
571	        fn(n->key, n->value, ctx);
572	    }
573	}
574	
575	/* In-order walk of one subtree, checking every rule at once.
576	 *
577	 * The error travels in the RETURN VALUE; the data travels in the pointer
578	 * parameters. *prev is the last key seen (NULL before the first); every key
579	 * must be strictly greater. *count accumulates the real node count.
580	 * *black_height receives this subtree's black-height, but only on success.
581	 *
582	 * Every recursive call is followed by an early return if it failed, so the
583	 * first broken rule found -- however deep -- comes straight back up untouched. */
584	static int validate_subtree(const struct rbnode *n, const char **prev,
585	                            size_t *count, size_t *black_height)
586	{
587	    if (n == NULL) {
588	        *black_height = 1;                  /* the invisible black leaf */
589	        return RB_OK;
590	    }
591	
592	    /* Checks on this node first, before descending. */
593	    if (n->left != NULL && n->left->parent != n) {
594	        return RB_BAD_PARENT;
595	    }
596	    if (n->right != NULL && n->right->parent != n) {
597	        return RB_BAD_PARENT;
598	    }
599	    if (n->color == RB_RED && (is_red(n->left) || is_red(n->right))) {
600	        return RB_BAD_RED_RED;
601	    }
602	
603	    size_t left_bh = 0;
604	    int rc = validate_subtree(n->left, prev, count, &left_bh);
605	    if (rc != RB_OK) {
606	        return rc;                          /* early abort */
607	    }
608	
609	    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
610	        return RB_BAD_ORDER;
611	    }
612	    *prev = n->key;
613	    (*count)++;
614	
615	    size_t right_bh = 0;
616	    rc = validate_subtree(n->right, prev, count, &right_bh);
617	    if (rc != RB_OK) {
618	        return rc;                          /* early abort */
619	    }
620	
621	    /* Only compare once BOTH sides came back clean. */
622	    if (left_bh != right_bh) {
623	        return RB_BAD_BLACK_HEIGHT;
624	    }
625	
626	    *black_height = left_bh + (n->color == RB_BLACK ? 1 : 0);
627	    return RB_OK;
628	}
629	
630	int rb_validate(const rbtree_t *t)
631	{
632	    if (t->root != NULL) {
633	        if (t->root->parent != NULL) {
634	            return RB_BAD_ROOT_PARENT;
635	        }
636	        if (t->root->color != RB_BLACK) {
637	            return RB_BAD_ROOT_COLOR;
638	        }
639	    }
640	
641	    const char *prev = NULL;
642	    size_t count = 0;
643	    size_t black_height = 0;                /* received, not compared: every
644	                                               path below already agreed */
645	    int rc = validate_subtree(t->root, &prev, &count, &black_height);
646	    if (rc != RB_OK) {
647	        return rc;
648	    }
649	    if (count != t->count) {
650	        return RB_BAD_COUNT;
651	    }
652	    return RB_OK;
653	}
654	
655	void rb_destroy(rbtree_t *t)
656	{
657	    if (t == NULL) {
658	        return;                 /* the header promises NULL-safety */
659	    }
660	
661	    /* Detach first, free second. Once the walk starts freeing nodes the old
662	     * subtree is unsafe to read, and value_free is caller code that might
663	     * read it (rb_find, rb_validate...). With root and count cleared, any
664	     * such call sees a valid empty tree instead of freed memory. */
665	    struct rbnode *root = t->root;
666	    t->root = NULL;
667	    t->count = 0;
668	
669	    /* Teardown by rotating the tree into a right spine (spec Figure 5). No
670	     * recursion, no allocation, and the only state is the one pointer root.
671	     * Colors and parent pointers go stale and are never read again: a tree
672	     * being destroyed does not have to stay a red-black tree.
673	     *
674	     * Invariant (DRAFT -- Nick to rewrite in his words): root reaches every
675	     * node not freed yet, and no node that has been freed.
676	     * Measure: total nodes plus nodes off the right spine. A rotation lifts
677	     * root->left onto the spine (one fewer off it); a free removes one spine
678	     * node (one fewer in total). Down by exactly 1 every time and never
679	     * negative, so the loop ends after at most 2n - 1 iterations. */
680	    while (root != NULL) {
681	        if (root->left != NULL) {
682	            struct rbnode *l = root->left;      /* right-rotate at root */
683	            root->left = l->right;
684	            l->right   = root;
685	            root       = l;
686	        } else {
687	            struct rbnode *next = root->right;  /* save it BEFORE root is freed */
688	            node_release(t, root);
689	            root = next;
690	        }
691	    }
692	
693	    pool_destroy(t->pool);      /* every slab, after the loop is done with them; NULL-safe */
694	    rb_free(t);
695	}
