          fault_alloc_total() - total0);

    fault_alloc_disarm();
    CHECK(c.n == N, "foreach visited %zu keys, expected %d", c.n, N);
    CHECK(values_freed == N, "destroy freed %d value(s), expected %d", values_freed, N);
    expect_clean("test_walk_and_destroy_allocate_nothing");
}''')
